Item.method_code:
const { getState, itemType, commandFactory } = options;
const state = getState();
const { selectedRows } = state.grid;
if (selectedRows.length !== 1) {
	return;
}

const rows = window.grid._grid.rows;
const selectedRowId = selectedRows[0];
const item = rows.get(selectedRowId);
const commandOptions = { itemType, item };
const commandAlias = target['command_alias@keyed_name'];
const openItemCommand = commandFactory(commandAlias, commandOptions);

return openItemCommand.execute();
